export function bindDragSafeClick(target, pointerTarget, action, options = {}) {
  const movementThreshold = Math.max(0, Number(options.movementThreshold) || 6);
  const schedule = options.schedule ?? ((callback) => setTimeout(callback, 0));
  const cancelSchedule = options.cancelSchedule ?? clearTimeout;
  let pointerStart = null;
  let dragged = false;
  let resetTimer = null;

  const reset = () => {
    pointerStart = null;
    dragged = false;
    if (resetTimer !== null) {
      cancelSchedule(resetTimer);
      resetTimer = null;
    }
  };
  const scheduleReset = () => {
    if (resetTimer !== null) cancelSchedule(resetTimer);
    resetTimer = schedule(() => {
      resetTimer = null;
      pointerStart = null;
      dragged = false;
    });
  };
  const markDragged = () => {
    dragged = true;
    scheduleReset();
  };
  const onPointerDown = (event) => {
    if (event.isPrimary === false) return;
    reset();
    pointerStart = {
      id: event.pointerId,
      x: Number(event.clientX) || 0,
      y: Number(event.clientY) || 0,
    };
  };
  const onPointerMove = (event) => {
    if (!pointerStart || event.pointerId !== pointerStart.id) return;
    const dx = (Number(event.clientX) || 0) - pointerStart.x;
    const dy = (Number(event.clientY) || 0) - pointerStart.y;
    if ((dx * dx) + (dy * dy) >= movementThreshold * movementThreshold) dragged = true;
  };
  const onPointerUp = (event) => {
    if (!pointerStart || event.pointerId !== pointerStart.id) return;
    scheduleReset();
  };
  const onPointerCancel = (event) => {
    if (!pointerStart || event.pointerId !== pointerStart.id) return;
    reset();
  };
  const onClick = (event) => {
    if (dragged) {
      event.preventDefault();
      event.stopPropagation();
      reset();
      return;
    }
    reset();
    action(event);
  };

  target.addEventListener("pointerdown", onPointerDown);
  target.addEventListener("click", onClick);
  pointerTarget.addEventListener("pointermove", onPointerMove, true);
  pointerTarget.addEventListener("pointerup", onPointerUp, true);
  pointerTarget.addEventListener("pointercancel", onPointerCancel, true);

  return {
    markDragged,
    destroy() {
      reset();
      target.removeEventListener("pointerdown", onPointerDown);
      target.removeEventListener("click", onClick);
      pointerTarget.removeEventListener("pointermove", onPointerMove, true);
      pointerTarget.removeEventListener("pointerup", onPointerUp, true);
      pointerTarget.removeEventListener("pointercancel", onPointerCancel, true);
    },
  };
}

export function statusWidgetPresentation(status, completed = false) {
  const revision = Number.isFinite(Number(status?.revision)) ? Number(status.revision) : 0;
  const relevant = Boolean(status?.chatId && (status?.caseMessageId || status?.profileSaved));
  if (!relevant) {
    return {
      visible: false,
      state: "inactive",
      label: "No active Date Simulator profile.",
    };
  }

  if (status?.processing === true || status?.code === "profile_saving") {
    return {
      visible: true,
      state: "updating",
      label: status?.processing
        ? "Updating scene and arc continuity…"
        : "Saving the private profile…",
    };
  }

  if (
    status?.level === "amber"
    || ["disabled", "permissions", "error", "invalid_profile", "migration_required", "recovered"].includes(status?.code)
  ) {
    return {
      visible: true,
      state: "attention",
      label: typeof status?.text === "string" && status.text
        ? status.text
        : "Continuity needs attention.",
    };
  }

  if (completed) {
    return {
      visible: true,
      state: "complete",
      label: `Continuity updated · Revision ${revision}.`,
    };
  }

  return {
    visible: true,
    state: "ready",
    label: revision > 0
      ? `Continuity current · Revision ${revision}.`
      : "Continuity ready.",
  };
}

export function resolveStatusWidgetPreference(status, pendingPreference) {
  if (typeof pendingPreference !== "boolean") {
    return { status, pendingPreference: null };
  }
  const savedPreference = status?.config?.showStatusWidget !== false;
  if (savedPreference === pendingPreference) {
    return { status, pendingPreference: null };
  }
  return {
    status: {
      ...status,
      config: {
        ...(status?.config ?? {}),
        showStatusWidget: pendingPreference,
      },
    },
    pendingPreference,
  };
}

export function profileCardPresentation(status) {
  const profileSaved = status?.profileSaved === true;
  const code = typeof status?.code === "string" ? status.code : "unknown";
  const text = typeof status?.text === "string" && status.text
    ? status.text
    : "Continuity Engine detected. Synchronizing private profile…";

  if (profileSaved) {
    return {
      state: "saved",
      label: "Private profile saved",
      text,
      level: status?.level === "amber" ? "amber" : "green",
      manual: false,
    };
  }

  if (code === "invalid_profile") {
    return {
      state: "invalid",
      label: "Private profile needs regeneration",
      text,
      level: "amber",
      manual: false,
    };
  }

  if (["disabled", "permissions", "error"].includes(code)) {
    return {
      state: "fallback",
      label: "Private profile ready",
      text,
      level: "amber",
      manual: true,
    };
  }

  return {
    state: "saving",
    label: "Saving private profile…",
    text,
    level: status?.level === "amber" ? "amber" : "green",
    manual: false,
  };
}

export function formatLocalTimestamp(value, locales, options = {}) {
  if (typeof value !== "string" || !value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  try {
    return new Intl.DateTimeFormat(locales, {
      dateStyle: "medium",
      timeStyle: "short",
      ...options,
    }).format(date);
  } catch {
    return date.toLocaleString();
  }
}

export function privateStatePresentation(visible, status, cached = null) {
  if (!visible) {
    return { text: "Private state is hidden.", cache: null };
  }
  if (!status?.chatId) {
    return { text: "No active chat.", cache: null };
  }

  let nextCache = cached?.chatId === status.chatId ? cached : null;
  if (Object.prototype.hasOwnProperty.call(status, "state")) {
    nextCache = { chatId: status.chatId, state: status.state };
  }
  return {
    text: nextCache
      ? JSON.stringify(nextCache.state, null, 2)
      : "Loading private state…",
    cache: nextCache,
  };
}

export function createButton(text, action, primary = false) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = `dsc-button${primary ? " dsc-button-primary" : ""}`;
  button.textContent = text;
  button.addEventListener("click", action);
  return button;
}

function createField(labelText, hintText = "") {
  const field = document.createElement("div");
  field.className = "dsc-field";
  const label = document.createElement("div");
  label.className = "dsc-label";
  label.textContent = labelText;
  const slot = document.createElement("div");
  slot.className = "dsc-control-slot";
  field.append(label, slot);
  let hint = null;
  if (hintText) {
    hint = document.createElement("div");
    hint.className = "dsc-hint";
    hint.textContent = hintText;
    field.appendChild(hint);
  }
  return { field, slot, hint };
}

function createFallbackDetails(title, expanded = false) {
  const details = document.createElement("details");
  details.className = "dsc-details";
  details.open = expanded;
  const summary = document.createElement("summary");
  summary.textContent = title;
  const body = document.createElement("div");
  body.className = "dsc-details-body";
  details.append(summary, body);
  return { element: details, body };
}

function supportsNativeComponents(ctx) {
  const names = [
    "mountBadge",
    "mountCheckbox",
    "mountNumericInput",
    "mountSelect",
    "mountSwitch",
  ];
  return names.every((name) => typeof ctx.components?.[name] === "function");
}

function isElementLike(value) {
  return Boolean(
    value
    && value.nodeType === 1
    && typeof value.matches === "function"
    && typeof value.querySelectorAll === "function",
  );
}

export function cardsInside(root) {
  const cards = [];
  const visited = new Set();

  function visit(scope) {
    if (!scope || visited.has(scope) || typeof scope.querySelectorAll !== "function") return;
    visited.add(scope);
    if (scope.shadowRoot) visit(scope.shadowRoot);

    if (isElementLike(scope)) {
      if (scope.matches(PROFILE_CARD_SELECTOR)) cards.push(scope);
      if (scope.matches(PROFILE_BUTTON_SELECTOR)) {
        const card = scope.closest?.(".ds-state-card");
        if (card) cards.push(card);
      }
      if (scope.matches(".ds-state-card") && scope.querySelector(PROFILE_BUTTON_SELECTOR)) {
        cards.push(scope);
      }
    }

    cards.push(...scope.querySelectorAll(PROFILE_CARD_SELECTOR));
    for (const button of scope.querySelectorAll(PROFILE_BUTTON_SELECTOR)) {
      const card = button.closest?.(".ds-state-card");
      if (card) cards.push(card);
    }
    for (const element of scope.querySelectorAll("*")) {
      if (element.shadowRoot) visit(element.shadowRoot);
    }
  }

  visit(root);
  return [...new Set(cards)];
}

export async function pickSetupFile(ctx, target, getActiveChatId) {
  if (typeof ctx.uploads?.pickFile !== "function") throw new Error("Update Lumiverse to use setup file imports.");
  const files = await ctx.uploads.pickFile({ accept: [".json", "application/json"], multiple: false, maxSizeBytes: 256 * 1024 });
  if (!files?.length) return null;
  if (getActiveChatId() !== target.chatId) throw new Error("The active chat changed. Choose the file again in the intended chat.");
  const file = files[0];
  if (file.sizeBytes > 256 * 1024 || file.bytes?.byteLength > 256 * 1024) throw new Error("Setup file exceeds 256 KB.");
  return new TextDecoder("utf-8", { fatal: true }).decode(file.bytes);
}

export const SETUP_FILENAME = "date-simulator-initial-setup.json";

// Call before any await/backend round trip so browsers retain user activation.
export function openSetupSavePicker(browserWindow) {
  if (browserWindow.isSecureContext === false || typeof browserWindow.showSaveFilePicker !== "function") return null;
  try {
    return Promise.resolve(browserWindow.showSaveFilePicker({
      suggestedName: SETUP_FILENAME,
      types: [{ description: "Date Simulator setup", accept: { "application/json": [".json"] } }],
    })).then((handle) => ({ handle }), (error) => ({ error }));
  } catch (error) { return Promise.resolve({ error }); }
}

export async function finishSetupSave(picker, fileText, isCurrent = () => true) {
  const result = await picker;
  if (!isCurrent()) return "stale";
  if (!result) return "download";
  if (result.error?.name === "AbortError") return "canceled";
  if (result.error) return "download";
  const writable = await result.handle.createWritable();
  try {
    if (!isCurrent()) { await writable.abort?.(); return "stale"; }
    await writable.write(fileText);
    if (!isCurrent()) { await writable.abort?.(); return "stale"; }
    await writable.close();
    return "saved";
  } catch (error) {
    try { await writable.abort?.(); } catch { /* retain the original write error */ }
    throw error;
  }
}

// A separate real click is required on hosts without the native save API.
// A data URL avoids relying on a Blob URL created in an asynchronous callback.
export function downloadSetupFile(fileText, ownerDocument) {
  const anchor = ownerDocument.createElement("a");
  anchor.href = `data:application/json;charset=utf-8,${encodeURIComponent(fileText)}`;
  anchor.download = SETUP_FILENAME;
  anchor.style.display = "none";
  anchor.addEventListener("click", (event) => event.stopPropagation());
  ownerDocument.body.appendChild(anchor);
  try { anchor.click(); } finally { anchor.remove(); }
}

